CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, display_name TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quotas(id TEXT PRIMARY KEY, name TEXT NOT NULL, max_hours INTEGER NOT NULL, used_hours INTEGER NOT NULL DEFAULT 0, max_budget_cents INTEGER NOT NULL, used_budget_cents INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY, teacher_id TEXT NOT NULL REFERENCES users(id), quota_id TEXT NOT NULL REFERENCES quotas(id), year INTEGER NOT NULL, status TEXT NOT NULL, requested_hours INTEGER NOT NULL, requested_budget_cents INTEGER NOT NULL, idempotency_key TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, due_at TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(teacher_id,year), UNIQUE(idempotency_key));
CREATE TABLE IF NOT EXISTS practices(id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), company_name TEXT NOT NULL, mentor_name TEXT NOT NULL, contact_email TEXT NOT NULL, status TEXT NOT NULL, planned_hours INTEGER NOT NULL, actual_hours INTEGER NOT NULL DEFAULT 0, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS evidences(id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), kind TEXT NOT NULL, title TEXT NOT NULL, uri TEXT NOT NULL, verification_status TEXT NOT NULL, submitted_by TEXT NOT NULL REFERENCES users(id), verified_by TEXT, verified_at TEXT, withdrawn_at TEXT, dispute_note TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES applications(id), reviewer_id TEXT NOT NULL REFERENCES users(id), reviewer_role TEXT NOT NULL, score INTEGER NOT NULL, decision TEXT NOT NULL, comment TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(application_id,reviewer_id));
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, outcome TEXT NOT NULL, request_id TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys(key TEXT PRIMARY KEY, actor_id TEXT NOT NULL, operation TEXT NOT NULL, response TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS worker_jobs(id TEXT PRIMARY KEY, job_type TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_run_at TEXT NOT NULL, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_applications_status ON applications(status, due_at);
CREATE INDEX IF NOT EXISTS idx_evidences_application ON evidences(application_id, verification_status);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_events(entity_type, entity_id, created_at);
CREATE INDEX IF NOT EXISTS idx_jobs_due ON worker_jobs(status, next_run_at);
